def prepare_ratio(done, available):
    if type(done) is not int or type(available) is not int:
        raise ValueError('counts must be integers')
    if done < 0 or available <= 0:
        raise ValueError('invalid count range')
    return {'completion_ratio': min(done / available, 1.0)}

def decide(features):
    return 'review' if features['completion_ratio'] < 0.5 else 'next'

assert decide(prepare_ratio(2, 10)) == 'review'

lab.testCode:
assert prepare_ratio(2, 10) == {'completion_ratio': 0.2}
assert prepare_ratio(20, 10) == {'completion_ratio': 1.0}
assert decide(prepare_ratio(2, 10)) == 'review'
assert decide(prepare_ratio(5, 10)) == 'next'
for args in ((True, 10), (2, False), (-1, 10), (2, 0)):
    try:
        prepare_ratio(*args)
    except ValueError:
        pass
    else:
        raise AssertionError(f'invalid counts accepted: {args}')
